"use strict";

const { describe, test, before, after, beforeEach } = require("node:test");
const assert = require("node:assert/strict");
const { createHash, randomUUID } = require("node:crypto");
const http = require("node:http");
const { createIdentitySessionStore } = require("../../src/identity-sessions");
const { createSessionHandler } = require("../../src/supervisor-session-handler");

const uri = process.env.SUPERVISOR_TEST_MONGODB_URI;
const password = "secure-session-passphrase";
// Generated by Python hashlib.scrypt, not by the implementation under test.
const passwordHash = "scrypt$32768$8$3$05050505050505050505050505050505$" +
  "ca11c67192cc87ee6897c100b896b31e3549d6d6080120d66614bcfac0b9fe09" +
  "5cfd50ce4c33c81527256fd44d0387a9187f7f8454b63e044c39310b845da012";
const id = "51c22a76-2fee-4820-aa99-22094e0b85df";
const clock = () => new Date("2030-01-01T00:00:00Z");
const digest = token => createHash("sha256").update(token, "ascii").digest("hex");

describe("Supervisor sessions with disposable MongoDB", { skip: !uri }, () => {
  let client, db, store;
  before(async () => {
    const { MongoClient } = require("mongodb");
    client = new MongoClient(uri, { serverSelectionTimeoutMS: 5000 });
    await client.connect();
    // No caller-selected database or existing volume is ever cleared.
    db = client.db("supervisor_session_test_" + randomUUID().replaceAll("-", ""));
    store = createIdentitySessionStore(db, { now: clock });
  });
  after(async () => {
    try { if (db) await db.dropDatabase(); }
    finally { if (client) await client.close(); }
  });
  beforeEach(async () => {
    for (const name of ["users", "sessions", "user_roles", "roles", "role_permissions", "permissions"]) {
      await db.collection(name).deleteMany({});
    }
    await db.collection("users").insertOne({
      _id: id, username: "reader", username_key: "reader", password_hash: passwordHash,
      account_status: "ACTIVE", revision: 3, role_codes: ["READER"], deleted_at: null,
    });
  });
  const login = target => (target || store).login({ username: "reader", password });

  test("persists only a digest, preserves account data and revokes after reconnect", async () => {
    const user = await db.collection("users").findOne({ _id: id });
    const session = await login();
    assert.deepEqual(session.principal.permissions, ["knowledge.read"]);
    const rows = await db.collection("sessions").find({}).toArray();
    assert.equal(rows.length, 1);
    assert.equal(rows[0]._id, digest(session.token));
    assert.equal(rows[0].identity_revision, 3);
    assert.equal(rows[0].expires_at - rows[0].created_at, 8 * 3600 * 1000);
    assert.equal(JSON.stringify(rows).includes(session.token), false);
    assert.deepEqual(await db.collection("users").findOne({ _id: id }), {
      ...user, last_login_at: clock(),
    });
    const { MongoClient } = require("mongodb");
    const reconnect = new MongoClient(uri);
    try {
      await reconnect.connect();
      const second = createIdentitySessionStore(reconnect.db(db.databaseName), { now: clock });
      assert.equal((await second.lookupSession("dk_session=" + session.token)).user_id, id);
      await second.logout("dk_session=" + session.token);
      assert.equal(await store.lookupSession("dk_session=" + session.token), null);
    } finally { await reconnect.close(); }
  });

  test("accepts legacy accounts without revision/deleted_at and resolves stored RBAC", async () => {
    await db.collection("users").updateOne({ _id: id }, {
      $unset: { revision: "", deleted_at: "", role_codes: "" },
    });
    await db.collection("user_roles").insertOne({ user_id: id, role_id: "legacy-role" });
    await db.collection("roles").insertOne({ _id: "legacy-role", code: "ADMIN" });
    await db.collection("role_permissions").insertOne({ role_id: "legacy-role", permission_id: "read" });
    await db.collection("permissions").insertOne({ _id: "read", code: "knowledge.read" });
    const session = await login();
    assert.ok(session);
    assert.deepEqual(session.principal.permissions, ["knowledge.read"]);
    assert.equal((await db.collection("sessions").findOne({ _id: digest(session.token) })).identity_revision, 1);
    assert.equal(Object.hasOwn(await db.collection("users").findOne({ _id: id }), "revision"), false);
  });

  test("reads historical KMS sessions and rejects expired, revised or disabled identities", async () => {
    const token = "a".repeat(64);
    const cookie = "dk_session=" + token;
    await db.collection("users").updateOne({ _id: id }, { $unset: { revision: "" } });
    await db.collection("sessions").insertOne({
      _id: digest(token), user_id: id, expires_at: new Date("2030-01-01T08:00:00Z"),
    });
    assert.equal((await store.lookupSession(cookie)).user_id, id);
    await db.collection("sessions").updateOne({ _id: digest(token) }, { $set: { expires_at: clock() } });
    assert.equal(await store.lookupSession(cookie), null);
    const session = await login();
    await db.collection("users").updateOne({ _id: id }, { $set: { revision: 2 } });
    assert.equal(await store.lookupSession("dk_session=" + session.token), null);
    const fresh = await login();
    await db.collection("users").updateOne({ _id: id }, { $set: { account_status: "DISABLED" } });
    assert.equal(await store.lookupSession("dk_session=" + fresh.token), null);
  });

  test("bad passwords and deleted accounts never create sessions", async () => {
    assert.equal(await store.login({ username: "reader", password: "incorrect" }), null);
    await db.collection("users").updateOne({ _id: id }, { $set: { deleted_at: clock() } });
    assert.equal(await login(), null);
    assert.equal(await db.collection("sessions").countDocuments({}), 0);
  });

  test("a legacy revision introduced concurrently cannot pass the optimistic guard", async () => {
    await db.collection("users").updateOne({ _id: id }, { $unset: { revision: "" } });
    const raced = { collection(name) {
      const real = db.collection(name);
      if (name !== "users") return real;
      return {
        findOne: (...args) => real.findOne(...args),
        updateOne: async (...args) => {
          await real.updateOne({ _id: id }, { $set: { revision: 1, role_codes: ["EDITOR"] } });
          return real.updateOne(...args);
        },
      };
    } };
    assert.equal(await login(createIdentitySessionStore(raced, { now: clock })), null);
    assert.equal(await db.collection("sessions").countDocuments({}), 0);
  });

  test("revocation between insert and introspection removes the new session", async () => {
    const raced = { collection(name) {
      const real = db.collection(name);
      if (name !== "sessions") return real;
      return {
        findOne: (...args) => real.findOne(...args),
        deleteOne: (...args) => real.deleteOne(...args),
        insertOne: async (...args) => {
          const result = await real.insertOne(...args);
          await db.collection("users").updateOne({ _id: id }, { $inc: { revision: 1 } });
          return result;
        },
      };
    } };
    assert.equal(await login(createIdentitySessionStore(raced, { now: clock })), null);
    assert.equal(await db.collection("sessions").countDocuments({}), 0);
  });

  test("private HTTP login/logout uses the real store and denies invalid service keys", async () => {
    const key = "b".repeat(64);
    const server = http.createServer(createSessionHandler({ gatewayKey: key, sessionStore: store }));
    await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
    const post = (endpoint, body, serviceKey = key) => fetch(
      "http://127.0.0.1:" + server.address().port + "/internal/v1/auth/" + endpoint, {
        method: "POST", headers: { "content-type": "application/json", "x-service-key": serviceKey },
        body: JSON.stringify(body),
      });
    try {
      assert.equal((await post("login", { username: "reader", password }, "bad")).status, 401);
      assert.equal(await db.collection("sessions").countDocuments({}), 0);
      const response = await post("login", { username: "reader", password });
      assert.equal(response.status, 200);
      const { session_token: token } = await response.json();
      assert.equal((await post("logout", { session_cookie: "dk_session=" + token })).status, 204);
      assert.equal(await store.lookupSession("dk_session=" + token), null);
    } finally { await new Promise(resolve => server.close(resolve)); }
  });
});
